code_example:
#include <iostream>
#include <vector>
#include <utility>

class Buffer {
public:
    std::vector<int> data;
    // Constructor
    Buffer(size_t size) : data(size) {
        std::cout << "Constructed Buffer of size " << size << std::endl;
    }
    // Move constructor
    Buffer(Buffer&& other) noexcept : data(std::move(other.data)) {
        std::cout << "Move constructor called" << std::endl;
    }
    // Move assignment
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            data = std::move(other.data);
            std::cout << "Move assignment called" << std::endl;
        }
        return *this;
    }
    // Deleted copy constructor and copy assignment to emphasize move semantics
    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;
};

int main() {
    Buffer buf1(10);
    Buffer buf2 = std::move(buf1); // Transfer resources from buf1 to buf2
    Buffer buf3(5);
    buf3 = std::move(buf2); // Transfer resources from buf2 to buf3
    return 0;
}
